import java.util.*;
import java.io.*;

public class Main {
    static class Step implements Comparable<Step> {
        long number;
        int totalCost;

        Step(long number, int totalCost) {
            this.number = number;
            this.totalCost = totalCost;
        }

        @Override
        public int compareTo(Step other) {
            // For PriorityQueue in Java, smallest element has highest priority
            // So, to mimic the C++ operator< which sorts by totalCost ascending,
            // we compare totalCost directly
            return Integer.compare(this.totalCost, other.totalCost);
        }
    }

    static Set<Long> visitedNodes = new HashSet<>();

    static boolean isAlreadyVisited(long c) {
        return visitedNodes.contains(c);
    }

    static Step getUupper(long n) {
        long res = 0;
        int digitsCount = 0;
        while (res < n) {
            res = res * 10 + 1;
            digitsCount++;
        }
        return new Step(res, digitsCount);
    }

    static Step getUpperLimit(long n) {
        long res = 0;
        int digitsCount = 0;
        while (res * 10 + 1 <= n) {
            res = res * 10 + 1;
            digitsCount++;
        }
        long baseRes = res;
        int baseDigits = digitsCount;
        while (res < n) {
            res += baseRes;
            digitsCount += baseDigits;
        }
        return new Step(res, digitsCount);
    }

    static Step getLowerLimit(long n) {
        long res = 0;
        int digitsCount = 0;
        while (res * 10 + 1 <= n) {
            res = res * 10 + 1;
            digitsCount++;
        }
        long baseRes = res;
        int baseDigits = digitsCount;
        while (res + baseRes <= n) {
            res += baseRes;
            digitsCount += baseDigits;
        }
        return new Step(res, digitsCount);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine());

        PriorityQueue<Step> pq = new PriorityQueue<>();
        pq.add(new Step(n, 0));

        while (pq.peek().number != 0) {
            Step current = pq.poll();
            long currentNumber = current.number;
            int currentCost = current.totalCost;

            if (isAlreadyVisited(currentNumber))
                continue;
            visitedNodes.add(currentNumber);

            for (Step s : Arrays.asList(getLowerLimit(currentNumber), getUpperLimit(currentNumber), getUupper(currentNumber))) {
                s.totalCost += currentCost;
                s.number = Math.abs(currentNumber - s.number);
                pq.add(s);
            }
        }

        System.out.println(pq.peek().totalCost);
    }
}
